<?php
declare(strict_types=1);

function gnre_task15_redirect(string $url,string $message,bool $error=false):void { $_SESSION[GNRE_SESSION]['task15_flash']=['message'=>$message,'error'=>$error];header('Location: '.$url,true,303);exit; }
/** Selection state may live in session; official rules always come from GNRE007. */
/** Task 15 is retained for compatibility only; it must not infer an environment. */
function gnre_task15_rules(array $context,string $uf,int $snapshotId=0):?array { return null; }
function gnre_task15_values():array {$out=[];foreach((array)($_POST['value_type']??[]) as $i=>$type){$amount=gnre_money((string)((array)($_POST['value_amount']??[])[$i]??''));if($type===''&&$amount===null)continue;if(!in_array($type,['11','12','21','22','31','32','41','42','51','52'],true)||$amount===null)throw new RuntimeException('Cada valor precisa de tipo oficial e valor positivo.');$out[]=['type'=>$type,'amount'=>$amount];}if(count($out)>10)throw new RuntimeException('Um item aceita no máximo 10 valores.');return $out;}
function gnre_task15_field(string $name,int $length,string $flag):string {$value=gnre_field($name,$length);if($value===null)throw new RuntimeException('Campo inválido: '.$name.'.');if($flag==='N')return '';if($flag==='S'&&$value==='')throw new RuntimeException('Campo obrigatório pela UF: '.$name.'.');return $value;}
function gnre_task15_retotal(mysqli $db,int $guide):void {$r=mysqli_query($db,'SELECT COALESCE(SUM(GNRE006_Valor),0) total FROM GNRE006 WHERE GNRE006_GNRE003_Id IN (SELECT GNRE003_Id FROM GNRE003 WHERE GNRE003_GNRE001_Id='.(int)$guide.')');$total=(string)(mysqli_fetch_assoc($r)['total']??'0.00');$q=mysqli_prepare($db,'UPDATE GNRE001 SET GNRE001_Valor=? WHERE GNRE001_Id=?');mysqli_stmt_bind_param($q,'si',$total,$guide);mysqli_stmt_execute($q);mysqli_stmt_close($q);}
function gnre_task15_clear_new_state(array $context):void { unset($_SESSION[GNRE_SESSION]['temporary']['task15'][(string)$context['company_id']]); }
function gnre_task15_has_types(?array $rules):bool { return is_array($rules)&&array_intersect(['0','1','2'],(array)($rules['uf_types']??[]))!==[]; }
function gnre_task15_drop_cached_rules(array $context,string $uf):void { unset($_SESSION[GNRE_SESSION]['config_uf'][(string)$context['company_id']][$uf]); }
/* Compatibilidade Task 15: cache sem tipos não é bloqueado no fluxo Task 18;
   a mensagem histórica era "não retornou tipos GNRE habilitados". */
function gnre_task15_can_delete(array $guide):bool { if(($guide['GNRE001_Status']??'')!=='R')return false;$db=gnre_db();$id=(int)$guide['GNRE001_Id'];$q=mysqli_prepare($db,'SELECT 1 FROM GNRE004 WHERE GNRE004_GNRE001_Id=? LIMIT 1');mysqli_stmt_bind_param($q,'i',$id);mysqli_stmt_execute($q);$r=mysqli_stmt_get_result($q);$has=$r&&mysqli_fetch_row($r);mysqli_stmt_close($q);mysqli_close($db);return !$has; }
function gnre_task15_delete_draft(mysqli $db,int $guideId,array $context):void {
    if(!mysqli_begin_transaction($db))throw new RuntimeException('Não foi possível iniciar a exclusão do rascunho.');
    try {$q=mysqli_prepare($db,"SELECT GNRE001_Status FROM GNRE001 WHERE GNRE001_Id=? AND GNRE001_C004_Id=? FOR UPDATE");mysqli_stmt_bind_param($q,'ii',$guideId,$context['company_id']);mysqli_stmt_execute($q);$r=mysqli_stmt_get_result($q);$guide=$r?mysqli_fetch_assoc($r):null;mysqli_stmt_close($q);if(!$guide)throw new RuntimeException('Guia não encontrada para a empresa GNRE selecionada.');if($guide['GNRE001_Status']!=='R')throw new RuntimeException('Esta guia possui histórico técnico e não pode ser excluída.');$q=mysqli_prepare($db,'SELECT 1 FROM GNRE004 WHERE GNRE004_GNRE001_Id=? LIMIT 1 FOR UPDATE');mysqli_stmt_bind_param($q,'i',$guideId);mysqli_stmt_execute($q);$r=mysqli_stmt_get_result($q);$technical=$r&&mysqli_fetch_row($r);mysqli_stmt_close($q);if($technical)throw new RuntimeException('Esta guia possui histórico técnico e não pode ser excluída.');foreach(['DELETE FROM GNRE006 WHERE GNRE006_GNRE003_Id IN (SELECT GNRE003_Id FROM GNRE003 WHERE GNRE003_GNRE001_Id=?)','DELETE FROM GNRE003 WHERE GNRE003_GNRE001_Id=?','DELETE FROM GNRE002 WHERE GNRE002_GNRE001_Id=?','DELETE FROM GNRE001 WHERE GNRE001_Id=? AND GNRE001_C004_Id=?'] as $index=>$sql){$q=mysqli_prepare($db,$sql);if($index===3)mysqli_stmt_bind_param($q,'ii',$guideId,$context['company_id']);else mysqli_stmt_bind_param($q,'i',$guideId);if(!mysqli_stmt_execute($q))throw new RuntimeException('Não foi possível excluir o rascunho com segurança.');mysqli_stmt_close($q);}mysqli_commit($db);}catch(Throwable $e){mysqli_rollback($db);throw $e;}
}
