 $id=(int)($_POST['guide_id']??0);$back=gnre_url('?edit='.$id);if($id){$snapshotDb=gnre_db();$snapshotGuide=gnre_get_guide($snapshotDb,$id,$context['company_id']);$snapshot=$snapshotGuide?GnreConfigUfSnapshot::forGuide($snapshotDb,$snapshotGuide,$context):null;mysqli_close($snapshotDb);if($snapshot)$_SESSION[GNRE_SESSION]['config_uf'][(string)$context['company_id']][(string)$snapshotGuide['GNRE001_UF_Favorecida']]=['rules'=>$snapshot['_rules'],'snapshot_id'=>(int)$snapshot['GNRE007_Id'],'at'=>time()];}
