 if($action==='task15_save_item'){try{$check=gnre_db();$draft=gnre_get_guide($check,$id,$context['company_id']);$checkRules=$draft?gnre_task15_rules($context,(string)$draft['GNRE001_UF_Favorecida']):null;$checkReceipt=$checkRules?GnreConfigUfRules::receipt($checkRules,(string)($_POST['receipt']??'')):null;if(!$checkReceipt)throw new RuntimeException('Receita não permitida pela configuração oficial.');foreach(['detail'=>'details','product'=>'products','period'=>'periods','document'=>'document_types'] as $field=>$list)if(($checkReceipt['fields'][$field]??'N')==='S'&&empty($checkReceipt[$list]))throw new RuntimeException('Configuração oficial incompleta: '.$field.' é obrigatório, mas a UF não forneceu opções para preenchimento.');mysqli_close($check);}catch(Throwable $e){if(isset($check))@mysqli_close($check);$_SESSION[GNRE_SESSION]['temporary']['task15_form'][(string)$context['company_id']][$id]=$_POST;gnre_task15_redirect($back,$e->getMessage(),true);}}
